```cpp
dimensions
[1 -3 0 0 0 0 0];
internalField
uniform 1.4;
boundaryField
{
    inlet1
    {
        type
        fixedValue;
        value
        $internalField;
    }
    inlet2
    {
        type
        fixedValue;
        value
        $internalField;
    }
    outlet
    {
        type
        codedFixedValue;
        value
        $internalField;
        name
        shockRho;
        code
        #{
            // Shock location (x)
            scalar xS =
            db().time().value()*11.2799
            + 0.74402;
            scalarField x =
            this->patch().Cf().component(0);
            operator==
            (
                pos(x - xS)*1.4
                + neg0(x-xS)*8.0
            );
        #};
    }
    walls
    {
        type
        zeroGradient;
    }
    defaultFaces
    {
        type
        empty;
    }
}
```

