Foam::compressibleBlastSystem::compressibleBlastSystem
(
    const label nPhases,
    const fvMesh& mesh
)
:
    compressibleSystem(mesh),
    IOdictionary
    (
        IOobject
        (
            "phaseProperties",
            mesh.time().constant(),
            mesh,
            IOobject::MUST_READ_IF_MODIFIED,
            IOobject::NO_WRITE
        )
    ),
    thermoPtr_
    (
        fluidBlastThermo::New(nPhases, mesh, *this)
    ),
    rho_(thermoPtr_->rho()),
    p_(thermoPtr_->p()),
    T_(thermoPtr_->T()),
    e_(thermoPtr_->he())
{
    thermoPtr_->validate("compressibleBlastSystem", "e");
}


