void Foam::CochranChan<Specie>::write(Ostream& os) const
{
    Specie::write(os);
    dictionary dict("equationOfState");
    dict.add("rho0", rho0_);
    dict.add("Gamma0", Gamma0_);
    dict.add("A", A_);
    dict.add("Epsilon1", Epsilon1_);
    dict.add("B", B_);
    dict.add("Epsilon2", Epsilon2_);
    dict.add("e0", e0_);
    os  << indent << dict.dictName() << dict;
}


