/*---------------------------------------------------------------------------*\
                           Class CochranChan Declaration
\*---------------------------------------------------------------------------*/

template<class Specie>
class CochranChan
:
    public Specie

{
// Private data

        //- Reference density
        scalar rho0_;

        //- Mie Grunsien coefficient
        scalar Gamma0_;

        //- Model coefficients
        scalar A_;
        scalar Epsilon1_;
        scalar B_;
        scalar Epsilon2_;

        //- Offset energy
        scalar e0_;


    // Private member functions

        //- Return deviation from ideal gas pressure
        inline scalar Pi
        (
            const scalar rho,
            const scalar e
        ) const;

        //- Return non-ideal speed of sound
        inline scalar delta
        (
            const scalar p,
            const scalar rho,
            const scalar e
        ) const;


public:


    // Constructors

        //- Construct from components
        inline CochranChan
        (
            const Specie& sp,
            const scalar rho0,
            const scalar Gamma0,

        const scalar A,
        const scalar Epsilon1,
        const scalar B,
        const scalar Epsilon2,
        const scalar e0
    );

    //- Construct from dictionary
    CochranChan(const dictionary& dict);

    //- Construct as named copy
    inline CochranChan
    (
        const word& name,
        const CochranChan&
    );

    //- Construct and return a clone
    inline autoPtr<CochranChan> clone() const;

    // Selector from dictionary
    inline static autoPtr<CochranChan> New
    (
        const dictionary& dict
    );


// Member Functions

    //- Return the instantiated type name
    static word typeName()
    {
        return
            "CochranChan<"
          + word(Specie::typeName_()) + '>';
    }

    //- Is temperature used
    static inline bool temperatureBased()
    {
        return false;
    }

    //- Is this a solid equation of state
    static inline bool solid()
    {
        return true;
    }

//- Return pressure
inline scalar p
(
    const scalar rho,
    const scalar e,
    const scalar T,
    const bool limit = true
) const;

//- Return density given temperature and pressure
inline scalar rho(const scalar p, const scalar T) const;

//- Return the MieGruniesen coefficient
inline scalar Gamma
(
    const scalar rho,
    const scalar e,
    const scalar T,
    const scalar Cv
) const;

//- Return the speed of sound
inline scalar cSqr
(
    const scalar p,
    const scalar rho,
    const scalar e,
    const scalar T,
    const scalar Cv
) const;

//- Return derivative of pressure w.r.t density
inline scalar dpdv
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Return derivative of pressure w.r.t. internal energy
inline scalar dpde
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Return derivative of pressure w.r.t. Temperature
inline scalar dpdT
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Internal energy correction [J/kg]
inline scalar E
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Enthalpy correction [J/kg]
inline scalar H
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Heat capacity at constant volume [J/kg/K]
inline scalar Cv
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Heat capacity at constant pressure [J/kg/K]
inline scalar Cp
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Heat capacity difference [J/kg/K]
inline scalar CpMCv
(
    const scalar rho,
    const scalar e,
    const scalar T,
    const scalar CpCv
) const;

    //- Entropy of mixture [J/kg/K]
    inline scalar S
    (
        const scalar p,
        const scalar T
    ) const;


    // IO

        //- Write to Ostream
        void write(Ostream& os) const;


// Member operators

    inline void operator+=(const CochranChan&);
    inline void operator*=(const scalar);


// Friend operators

    friend CochranChan operator+ <Specie>
    (
        const CochranChan&,
        const CochranChan&
    );

    friend CochranChan operator* <Specie>
    (
        const scalar s,
        const CochranChan&
    );

    friend CochranChan operator== <Specie>
    (
        const CochranChan&,
        const CochranChan&
    );


// Ostream Operator

    friend Ostream& operator<< <Specie>
    (
        Ostream&,
        const CochranChan&

    B_(B),
    Epsilon2_(Epsilon2),
    e0_(e0)
{}


template<class Specie>
Foam::scalar Foam::CochranChan<Specie>::Pi
(
    const scalar rho,
    const scalar e
) const
{
    scalar rhos(max(rho, 1e-10));
    return
        Gamma0_*rho
       *(
          - A_/((1.0 - Epsilon1_)*rho0_)*(pow(rho0_/rhos, 1.0 - Epsilon1_) - 1.0)
          + B_/((1.0 - Epsilon2_)*rho0_)*(pow(rho0_/rhos, 1.0 - Epsilon2_) - 1.0)
        )
      - A_*pow(rho0_/rhos, -Epsilon1_) + B_*pow(rho0_/rhos, -Epsilon2_)
      - e0_*rho*Gamma0_;
}


template<class Specie>
Foam::scalar Foam::CochranChan<Specie>::delta
(
    const scalar p,
    const scalar rho,
    const scalar e
) const
{
    scalar rhos(max(rho, 1e-10));
    return
      (
           -A_
           *(
               Epsilon1_*pow(rho0_/rhos, -Epsilon1_)
              *(Epsilon1_ - Gamma0_ - 1.0)/rhos
             + Gamma0_/rho0_
            )/(Epsilon1_ - 1.0)
          + B_
           *(
               Epsilon2_*pow(rho0_/rhos, -Epsilon2_)
              *(Epsilon2_ - Gamma0_ - 1.0)/rhos
             + Gamma0_/rho0_
            )/(Epsilon2_ - 1.0)

          - Gamma0_*e0_
        )/Gamma0_;
}


