/*---------------------------------------------------------------------------*\
                           Class DoanNickel Declaration
\*---------------------------------------------------------------------------*/

template<class Specie>
class DoanNickel
:

    public Specie
{
// Private data

    //- Reference density
    scalar rho0_ = 1.293;

    //- Gamma coefficients
    scalar a_ = 0.161;
    scalar b_ = 0.255;
    scalar c_ = 0.280;
    scalar d_ = 0.137;
    scalar g_ = 0.050;

    scalar a1_ = 0.048;
    scalar a2_ = 0.032;
    scalar a3_ = 0.045;

    //- Equation of state coefficients for first regime
    //  O_2 -> 2O
    scalar E1_ = 4.46;
    scalar E11_ = 0.357;
    scalar E1Offset_ = 8.5;
    scalar deltaE1_ = 0.975;
    scalar deltaE1Pow_ = 0.05;

