    inline void operator+=(const JWL&);
    inline void operator*=(const scalar);


// Friend operators

    friend JWL operator+ <Specie>
    (
        const JWL&,
        const JWL&
    );

    friend JWL operator* <Specie>
    (
        const scalar s,
        const JWL&
    );

    friend JWL operator== <Specie>
    (
        const JWL&,
        const JWL&
    );

    omega_(omega),
    gammaIdeal_(gammaIdeal),
    A_(A),
    B_(B),
    R1_(R1),
    R2_(R2),
    e0_(e0)
{}


template<class Specie>
Foam::scalar Foam::JWL<Specie>::Pi
(
    const scalar rho,
    const scalar e
) const
{
    if (rho < rhoCutOff_)
    {
        return 0.0;
    }

    scalar V(rho0_/max(rho, 1e-10));
    return
        A_*(omega_/(R1_*V) - 1.0)*exp(-R1_*V)
      + B_*(omega_/(R2_*V) - 1.0)*exp(-R2_*V)
      - omega_*rho*e0_;

}


template<class Specie>
Foam::scalar Foam::JWL<Specie>::delta
(
    const scalar p,
    const scalar rho,
    const scalar e
) const
{
    if (rho < rhoCutOff_)
    {
        return 0.0;
    }

    scalar rhos(max(rho, 1e-10));
    return
        (
            A_*exp(-R1_*rho0_/rhos)

           *(omega_*(1.0/(R1_*rho0_) + 1.0/rhos) - R1_*rho0_/sqr(rhos))
          + B_*exp(-R2_*rho0_/rhos)
           *(omega_*(1.0/(R2_*rho0_) + 1.0/rhos) - R2_*rho0_/sqr(rhos))
          - omega_*e0_
        )/omega_;
}


