template<class Specie>
void Foam::LSZK<Specie>::write(Ostream& os) const
{
    Specie::write(os);
    dictionary dict("equationOfState");
    dict.add("b", b_);
    dict.add("a", a_);
    dict.add("gamma", gamma_);
    os  << indent << dict.dictName() << dict;
}


