// * * * * * * * * * * * * * * * Member Operators  * * * * * * * * * * * * * //

template<class Specie>
inline void Foam::Tait<Specie>::operator+=
(
    const Tait<Specie>& pf
)
{
    scalar Y1 = this->Y();
    Specie::operator+=(pf);

    if (mag(this->Y()) > SMALL)
    {
        Y1 /= this->Y();
        const scalar Y2 = pf.Y()/this->Y();

        scalar gamma1 = gamma_;
        scalar w1 = Y1/(gamma_ - 1.0);
        scalar w2 = Y2/(pf.gamma_ - 1.0);
        gamma_ = 1.0/(w1 + w2) + 1.0;

        w1 *= gamma1;
        w2 *= pf.gamma_;
        a_ = (gamma_ - 1.0)/gamma_*(a_*w1 + pf.a_*w2);
        b_ = (gamma_ - 1.0)/gamma_*(b_*w1 + pf.b_*w2);
    }
}


template<class Specie>
inline void Foam::Tait<Specie>::operator*=(const scalar s)
{
    Specie::operator*=(s);
}


// * * * * * * * * * * * * * * * Friend Operators  * * * * * * * * * * * * * //

template<class Specie>
inline Foam::Tait<Specie> Foam::operator+
(
    const Tait<Specie>& pf1,
    const Tait<Specie>& pf2
)
{
    Specie sp
    (
        static_cast<const Specie&>(pf1)
      + static_cast<const Specie&>(pf2)
    );

    if (mag(sp.Y()) < SMALL)
    {
        return Tait<Specie>
        (
            sp,
            pf1.a_,
            pf1.b_,
            pf1.gamma_
        );
    }
    else
    {
        const scalar Y1 = pf1.Y()/sp.Y();
        const scalar Y2 = pf2.Y()/sp.Y();

        scalar w1 = Y1/(pf1.gamma_ - 1.0);
        scalar w2 = Y2/(pf2.gamma_ - 1.0);

        scalar gamma = 1.0/(w1 + w2) + 1.0;
        scalar coeff((gamma - 1.0)/gamma);

        return Tait<Specie>
        (
            sp,
            coeff*(w1*pf1.a_ + w2*pf2.a_),
            coeff*(w1*pf1.b_ + w2*pf2.b_),
            gamma
        );
    }
}


template<class Specie>
inline Foam::Tait<Specie> Foam::operator*
(
    const scalar s,
    const Tait<Specie>& pf
)
{
    return Tait<Specie>
    (
        s*static_cast<const Specie&>(pf),
        pf.a_,
        pf.b_,
        pf.gamma_
    );
}


template<class Specie>
inline Foam::Tait<Specie> Foam::operator==
(
    const Tait<Specie>& pf1,
    const Tait<Specie>& pf2
)
{
    Specie sp
    (
        static_cast<const Specie&>(pf1)
     == static_cast<const Specie&>(pf2)
    );

    const scalar Y1 = pf1.Y()/sp.Y();
    const scalar Y2 = pf2.Y()/sp.Y();

    scalar w1 = Y1/(pf1.gamma_ - 1.0);

scalar T = 300;

scalar rhoMin = dict.subDict("equationOfState").lookupOrDefault<scalar>
(
    "rhoMin",
    0.5*rho0_
);
scalar rhoMax = dict.subDict("equationOfState").lookupOrDefault<scalar>
(
    "rhoMax",
    5.0*rho0_
);

label n = 2000;
scalar dRho = (rhoMax - rhoMin)/scalar(n);
scalar n1 = (rho0_ - rhoMin)/dRho;
scalar n2 = n - n1;

label stepsPerEntry(n/tableSize);

label I = n1/stepsPerEntry+1;
scalar rho = rho0_;
scalar ec = 0.0;
for (label i = 0; i < n2; i++)
{
    scalar ecOld = ec;

    scalar k1 = p(rho, ec, T)/sqr(rho);
    ec = ecOld + dRho*0.5*k1;

    rho += 0.5*dRho;
    scalar k2 = p(rho, ec, T)/sqr(rho);
    ec = ecOld + dRho*0.5*k2;
    scalar k3 = p(rho, ec, T)/sqr(rho);

    ec = ecOld + dRho*k3;
    rho += 0.5*dRho;
    scalar k4 = p(rho, ec, T)/sqr(rho);

    ec = ecOld + dRho/6.0*(k1 + 2.0*(k2 + k3) + k4);

    if (((i + 1) % label(n/tableSize)) == 0)
    {
        rhof[I] = rho;
        ecf[I] = ec;
        I++;
    }

    }

    I = n1/stepsPerEntry;
    rho = rho0_;
    ec = 0.0;
    dRho *= -1;
    for (label i = 0; i < n1; i++)
    {
        scalar ecOld = ec;

        scalar k1 = p(rho, ec, T)/sqr(rho);
        ec = ecOld + dRho*0.5*k1;

        rho += 0.5*dRho;
        scalar k2 = p(rho, ec, T)/sqr(rho);
        ec = ecOld + dRho*0.5*k2;
        scalar k3 = p(rho, ec, T)/sqr(rho);

        ec = ecOld + dRho*k3;
        rho += 0.5*dRho;
        scalar k4 = p(rho, ec, T)/sqr(rho);

        ec = ecOld + dRho/6.0*(k1 + 2.0*(k2 + k3) + k4);

        if (((i - 1) % (n/tableSize)) == 0)
        {
            rhof[I] = rho;
            ecf[I] = ec;
            I--;
        }
    }

    EcTable_.set
    (
        rhof,
        ecf,
        "none",
        "none",
        "linearExtrapolated",
        true
    );
}


