template<class Specie>
Foam::scalar Foam::Tillotson<Specie>::p
(
    const scalar rho,
    const scalar e,
    const scalar T,
    const bool limit
) const
{
    scalar eta(rho/rho0_);
    scalar mu(eta - 1.0);
    scalar res =
        (a_ + b_/(e/(e0_*sqr(eta)) + 1.0))*rho*e
      + A_*mu
      + B_*sqr(mu);

      return limit ? max(res, pCav_) : res;
}


