template<class Specie>
Foam::scalar Foam::linearTillotson<Specie>::Pi
(
    const scalar rho,
    const scalar e
) const
{
    scalar mu(rho/rho0_ - 1.0);
    return
        omega_*rho*e0_
      - p0_
      - A_*mu
      - B_*sqr(mu)
      - C_*pow3(mu);
}


template<class Specie>
Foam::scalar Foam::linearTillotson<Specie>::delta
(
    const scalar p,
    const scalar rho,
    const scalar e
) const
{
    scalar mu(rho/rho0_ - 1.0);
    return
        e0_
      - (
            A_
          + 2.0*B_*mu
          + 3.0*C_*sqr(mu)
        )/(rho0_*omega_);
}


