template<class Specie>
Foam::scalar Foam::linearTillotson<Specie>::p
(
    const scalar rho,

    const scalar e,
    const scalar T,
    const bool limit
) const
{
    scalar mu(rho/rho0_ - 1.0);
    scalar pressure =
        p0_
      + omega_*rho*(e - e0_)
      + A_*mu
      + B_*sqr(mu)
      + C_*pow3(mu);

    return limit ? max(pressure, pCav_) : pressure;
}


