           *(R1_*rho0_ - omega_*rho*(1.0 + rho/R1_/rho0_))
          + B_*exp(-R2_*rho0_/rhos)
           *(R2_*rho0_ - omega_*rho*(1.0 + rho/R2_/rho0_))
          + omega_*(e + e0_)*sqr(rhos)
        );
}


