template<class Specie>
Foam::scalar Foam::solidJWL<Specie>::CpMCv
(
    const scalar rho,
    const scalar e,
    const scalar T,
    const scalar CpCv
) const
{
    return this->eBased_ ? omega_*CpCv : CpCv*omega_/(omega_ + 1.0);
}


template<class Specie>
Foam::scalar Foam::solidJWL<Specie>::E
(
    const scalar rho,
    const scalar e,
    const scalar T
) const
{
    scalar rhos = max(rho, 1e-10);

    scalar V(rho0_/rhos);
    return (A_/R1_*exp(-R1_*V) + B_/R2_*exp(-R2_*V))/rho0_ - e0_;
}


template<class Specie>
Foam::scalar Foam::solidJWL<Specie>::H
(
    const scalar rho,
    const scalar e,
    const scalar T
) const
{
    scalar rhos(max(rho, 1e-10));
    return
        A_*(1.0/rhos + 1.0/(R1_*rho0_))*exp(-R1_*rho0_/rhos)
      + B_*(1.0/rhos + 1.0/(R2_*rho0_))*exp(-R2_*rho0_/rhos)
      + e0_*omega_*log(rhos);
}


