template<class Specie>
Foam::scalar Foam::vanderWaals<Specie>::p
(
    const scalar rho,
    const scalar e,
    const scalar T,

    const bool limit
) const
{
    return
        limit
      ? max((GammaMG(rho, e) - 1.0)*rho*e - Pi(rho, e), 0.0)
      : (GammaMG(rho, e) - 1.0)*rho*e - Pi(rho, e);
}


