template<class Specie>
void Foam::BKW<Specie>::write(Ostream& os) const
{
    Specie::write(os);
    dictionary dict("equationOfState");
    dict.add("k", k_);
    dict.add("kappa", kappa_);
    dict.add("Theta", Theta_);
    dict.add("a", a_);
    dict.add("beta", beta_);
    os  << indent << dict.dictName() << dict;
}


