    const scalar T
) const
{
    NotImplemented;
    return 0.0;
}


// * * * * * * * * * * * * * * * Member Operators  * * * * * * * * * * * * * //

template<class Specie>
inline void Foam::BKW<Specie>::operator+=
(
    const BKW<Specie>& pf
)
{
    scalar Y1 = this->Y();
    Specie::operator+=(pf);

    if (mag(this->Y()) > SMALL)
    {
        Y1 /= this->Y();
        const scalar Y2 = pf.Y()/this->Y();

        k_ = Y1*k_ + Y2*pf.k_;
        kappa_ = Y1*kappa_ + Y2*pf.kappa_;
        Theta_ = Y1*Theta_ + Y2*pf.Theta_;
        a_ = Y1*a_ + Y2*pf.a_;
        beta_ = Y1*beta_ + Y2*pf.beta_;
    }
}


template<class Specie>
inline void Foam::BKW<Specie>::operator*=(const scalar s)
{
    Specie::operator*=(s);
}


// * * * * * * * * * * * * * * * Friend Operators  * * * * * * * * * * * * * //

template<class Specie>
inline Foam::BKW<Specie> Foam::operator+
(
    const BKW<Specie>& pf1,
    const BKW<Specie>& pf2
)

{
    Specie sp
    (
        static_cast<const Specie&>(pf1)
      + static_cast<const Specie&>(pf2)
    );

    if (mag(sp.Y()) < SMALL)
    {
        return BKW<Specie>
        (
            sp,
            pf1.k_,
            pf1.kappa,
            pf1.Theta_,
            pf1.a_,
            pf1.beta_
        );
    }
    else
    {
        const scalar Y1 = pf1.Y()/sp.Y();
        const scalar Y2 = pf2.Y()/sp.Y();

        return BKW<Specie>
        (
            sp,
            Y1*pf1.k_ + Y2*pf2.k_,
            Y1*pf1.kappa_ + Y2*pf2.kappa,
            Y1*pf1.Theta_ + Y2*pf2.Theta_,
            Y1*pf1.a_ + Y2*pf2.a_,
            Y1*pf1.beta_ + Y2*pf2.beta_
        );
    }
}


template<class Specie>
inline Foam::BKW<Specie> Foam::operator*
(
    const scalar s,
    const BKW<Specie>& pf
)
{
    return BKW<Specie>
    (
        s*static_cast<const Specie&>(pf),
        pf.k_,

        pf.kappa,
        pf.Theta_,
        pf.a_,
        pf.beta_
    );
}


template<class Specie>
inline Foam::BKW<Specie> Foam::operator==
(
    const BKW<Specie>& pf1,
    const BKW<Specie>& pf2
)
{
    Specie sp
    (
        static_cast<const Specie&>(pf1)
     == static_cast<const Specie&>(pf2)
    );

    const scalar Y1 = pf1.Y()/sp.Y();
    const scalar Y2 = pf2.Y()/sp.Y();

    return BKW<Specie>
    (
        sp,
        Y2*pf2.k_ - Y1*pf1.k_,
        Y2*pf2.kappa_ - Y1*pf1.kappa,
        Y2*pf2.Theta_ - Y1*pf1.Theta_,
        Y2*pf2.a_ - Y1*pf1.a_,
        Y2*pf2.beta_ - Y1*pf1.beta_
    );
}


