template<class Specie>
Foam::scalar Foam::BirchMurnaghan3<Specie>::E
(
    const scalar rho,
    const scalar e,
    const scalar T
) const
{
    return
        (
            9.0/16.0*K0_
           *(
                cbrt(pow5(rho/rho0_))
               *(
                   cbrt(sqr(rho/rho0_))*(14.0 - 3.0*K0Prime_)
                 + 3.0*K0Prime_ - 16.0
                )
              + pow3(rho/rho0_)*(K0Prime_ - 4.0)
            )
          - pRef_
        )/max(rho, 1e-10);
}


