) const
{
    return
        3.0*K0_
       *(
            9.0*K0Prime_*sqr(rho)
          + pow(rho, 2.0/3.0)*pow3(rho0_)
           *(
              - 21.0*K0Prime_*pow(rho/rho0_, 2.0/3.0)
              + 15.0*K0Prime_
              + 98.0*pow(rho/rho0_, 2.0/3.0)
              - 80.0
            )*pow(rho0_, -5.0/3.0)
          - 36.0*sqr(rho)
        )/(16.0*pow3(rho0_));
}


