template<class Specie>
void Foam::JWLC<Specie>::write(Ostream& os) const
{
    Specie::write(os);
    dictionary dict("equationOfState");
    dict.add("rho0", rho0_);
    dict.add("omega", omega_);
    dict.add("A", A_);
    dict.add("B", B_);
    dict.add("C", C_);
    dict.add("R1", R2_);
    dict.add("R2", R2_);
    os  << indent << dict.dictName() << dict;
}


