template<class Specie>
Foam::scalar Foam::JWLC<Specie>::pRhoT
(
    const scalar rho,
    const scalar T
) const
{
    scalar V(rho0_/max(rho, 1e-10));
    return A_*exp(-R1_*V) + B_*exp(-R2_*V) + C_/pow(V, omega_ + 1.0);
}


