    const scalar T
) const
{
    scalar V(rho0_/max(rho, 1e-10));
    return
        (
            A_/R1_*exp(-R1_*V)
          + B_/R2_*exp(-R2_*V)
          + C_/(omega_*pow(V, omega_))
        )/rho0_;
}


