template<class Specie>
Foam::scalar Foam::JWLC<Specie>::H
(
    const scalar rho,
    const scalar e,
    const scalar T
) const
{
    scalar rhos(max(rho, 1e-10));
    scalar V(rho0_/rhos);
    return
      - (
            A_*R1_*rho0_*exp(-R1_*V)
          + B_*R2_*rho0_*exp(-R2_*V)
        )/(2.0*sqr(rhos))
      - C_*(omega_ + 1.0)*pow(V, -omega_)/(2.0*rho0_);
}


