template<class Specie>
inline Foam::JWLC<Specie> Foam::operator+
(
    const JWLC<Specie>& pf1,
    const JWLC<Specie>& pf2
)
{
    Specie sp
    (
        static_cast<const Specie&>(pf1)
      + static_cast<const Specie&>(pf2)
    );

    if (mag(sp.Y()) < SMALL)
    {
        return JWLC<Specie>
        (
            sp,
            pf1.rho0_,
            pf1.omega_,
            pf1.A_,
            pf1.B_,
            pf1.C_,
            pf1.R1_,
            pf1.R2_
        );
    }
    else
    {
        const scalar Y1 = pf1.Y()/sp.Y();
        const scalar Y2 = pf2.Y()/sp.Y();

        return JWLC<Specie>
        (
            sp,
            Y1*pf1.rho0_ + Y2*pf2.rho0_,
            Y1*pf1.omega_ + Y2*pf2.omega_,
            Y1*pf1.A_ + Y2*pf2.A_,
            Y1*pf1.B_ + Y2*pf2.B_,
            Y1*pf1.C_ + Y2*pf2.C_,
            Y1*pf1.R1_ + Y2*pf2.R1_,
            Y1*pf1.R2_ + Y2*pf2.R2_
        );
    }
}

template<class Specie>
inline Foam::JWLC<Specie> Foam::operator*
(
    const scalar s,
    const JWLC<Specie>& pf
)
{
    return JWLC<Specie>
    (
        s*static_cast<const Specie&>(pf),
        pf.rho0_,
        pf.omega_,
        pf.A_,
        pf.B_,
        pf.C_,
        pf.R1_,
        pf.R2_
    );
}


template<class Specie>
inline Foam::JWLC<Specie> Foam::operator==
(
    const JWLC<Specie>& pf1,
    const JWLC<Specie>& pf2
)
{
    Specie sp
    (
        static_cast<const Specie&>(pf1)
     == static_cast<const Specie&>(pf2)
    );

    const scalar Y1 = pf1.Y()/sp.Y();
    const scalar Y2 = pf2.Y()/sp.Y();

    return JWLC<Specie>
    (
        sp,
        Y2*pf2.rho0_ - Y1*pf1.rho0_,
        Y2*pf2.omega_ - Y1*pf1.omega_,
        Y2*pf2.A_ - Y1*pf1.A_,
        Y2*pf2.B_ - Y1*pf1.B_,
        Y2*pf2.C_ - Y1*pf1.C_,
        Y2*pf2.R1_ - Y1*pf1.R1_,
        Y2*pf2.R2_ - Y1*pf1.R2_

        K0_ = 1.0/max(kappa_, small);
    }
    else
    {
        K0_ = eosDict.lookup<scalar>("K0");
        kappa_ = 1.0/max(K0_, small);
    }

    if (eosDict.found("n"))
    {
        n_ = eosDict.lookup<scalar>("n");
        K0Prime_ = n_;
    }
    else
    {
        K0Prime_ =  eosDict.lookupOrDefault<scalar>("K0Prime", 1.0 + small);
        n_ = K0Prime_;
    }
}


