:
    public Specie
{
// Private data

    //- Pressure lookup table
    scalarLookupTable2D pTable_;

    //- Temperature lookup table
    scalarLookupTable2D TTable_;


public:

    //- Construct from components
        inline tabulatedThermoEOS
        (
            const Specie& sp
        );

