        // Selector from dictionary
        inline static autoPtr<tabulatedThermoEOS> New
        (
            const dictionary& dict
        );


    //- Return the instantiated type name
        static word typeName()
        {
            return
                "eTabulated<tabulatedMG<"
              + word(Specie::typeName_()) + ">>";
        }


    // Member Functions

        //- Is temperature used
        bool temperatureBased() const
        {
            return false;
        }

// Equation of state functions

    //- Return limited pressure
    inline scalar pRhoT
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Return pressure
    inline scalar p
    (
        const scalar rho,
        const scalar e,
        const scalar T,
        const bool limit = true
    ) const;

    //- Return density given temperature and pressure
    inline scalar rho(const scalar p, const scalar T) const;

    //- Return derivative of pressure w.r.t. specific volume
    inline scalar dpdv
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Return derivative of pressure w.r.t. specific density
    inline scalar dpdRho
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Return derivative of pressure w.r.t. Temperature
    inline scalar dpdT
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Return derivative of pressure w.r.t. internal energy

    inline scalar dpde
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

// Thermodynamic functions

    //- Return Mie Gruniesen coefficient
    inline scalar Gamma
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Return speed of sound
    inline scalar cSqr
    (
        const scalar p,
        const scalar rho,
