        const scalar T
    ) const;

    //- Heat capacity at constant volume [J/kg/K]
    inline scalar Cv
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Heat capacity at constant pressure [J/kg/K]
    inline scalar Cp
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Heat capacity difference [J/kg/K]
    inline scalar CpMCv
    (
        const scalar rho,
        const scalar e,
        const scalar T,

    const scalar CpCv
) const;

//- Return specific heat ratio
inline scalar CpByCv
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Sensible internal energy [J/kg]
inline scalar Es
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Absolute internal energy [J/kg]
inline scalar Ea
(
    const scalar rho,
