) const;

//- Absolute enthalpy [J/kg]
inline scalar Ha
(
    const scalar rho,
    const scalar e,
    const scalar T
) const;

//- Heat of formation [J/kg]
inline scalar Hf() const;

//- Flame temperature [K]
inline scalar flameT() const;

        //- Entropy [J/kg/K]
        inline scalar S
        (
            const scalar p,
