        ) const;

        //- Return temperature
        inline scalar TRhoE
        (
            const scalar T0,
            const scalar rho,
            const scalar e
        ) const;

        //- Initialize internal energy
        inline scalar initializeEnergy
        (
            const scalar p,
            const scalar rho,
            const scalar e,
            const scalar T
        ) const;

        //- Initialize internal energy
        inline scalar rhoPT
        (
            const scalar rho,
            const scalar p,
            const scalar T
        ) const;

    // Member operators

    inline void operator+=(const tabulatedThermoEOS&);
    inline void operator*=(const scalar);


// Friend operators

    friend tabulatedThermoEOS operator+ <Specie>
