    const scalar T
) const
{
    return p(rho, e, T, true);
}


template<class Specie>

Foam::scalar Foam::tabulatedThermoEOS<Specie>::p
(
    const scalar rho,
    const scalar e,
    const scalar T,
    const bool limit
) const
{
    return
        limit
      ? max(pTable_.lookup(rho, e), 0.0)
      : pTable_.lookup(rho, e);
}


