inline Foam::scalar Foam::eIcoTabulatedThermo<EquationOfState>::limit
(
    const scalar T,
    const scalar Told
) const
{
    if (T/Told > 5.0)
    {
        return Told*5.0;
    }

    if
    (
        eIcoTabulatedThermo<EquationOfState>::debug
     && (T < Tlow_ || T > Thigh_)
    )
    {
        WarningInFunction
            << "attempt to use eIcoTabulatedThermo<EquationOfState>"
               " out of temperature range "
            << Tlow_ << " -> " << Thigh_ << ";  T = " << T
            << endl;
    }
    return min(max(T, Tlow_), Thigh_);
}


