    //- Return derivative of pressure w.r.t temperature
    inline scalar dpdT
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Return speed of sound
    inline scalar cSqr
    (
        const scalar p,

        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Return specific heat ratio
    inline scalar CpByCv
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Initialize internal energy
    inline scalar initializeEnergy
    (
        const scalar p,
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Initialize internal energy
    inline scalar rhoPT
    (
        const scalar rho,
        const scalar p,
        const scalar T
    ) const;


// Mass specific derived properties

        //- Gibbs free energy [J/kg]
        inline scalar G
        (
            const scalar p,
            const scalar T
        ) const;

        //- Helmholtz free energy [J/kg]
        inline scalar A
        (
            const scalar p,
            const scalar T
        ) const;

// Equilibrium reaction thermodynamics

        //- Equilibrium constant [] i.t.o fugacities
        //  = PIi(fi/Pstd)^nui
        inline scalar K
        (
            const scalar p,
            const scalar T
        ) const;

        //- Equilibrium constant [] i.t.o. partial pressures
        //  = PIi(pi/Pstd)^nui
        //  For low pressures (where the gas mixture is near perfect) Kp = K
        inline scalar Kp
        (
            const scalar p,
            const scalar T
        ) const;

        //- Equilibrium constant i.t.o. molar concentration
        //  = PIi(ci/cstd)^nui
        //  For low pressures (where the gas mixture is near perfect)
        //  Kc = Kp(pstd/(RR*T))^nu
        inline scalar Kc
        (
            const scalar p,
            const scalar T
        ) const;

        //- Equilibrium constant [] i.t.o. mole-fractions
        //  For low pressures (where the gas mixture is near perfect)
        //  Kx = Kp(pstd/p)^nui
        inline scalar Kx
        (
            const scalar p,
            const scalar T
        ) const;

        //- Equilibrium constant [] i.t.o. number of moles
        //  For low pressures (where the gas mixture is near perfect)
        //  Kn = Kp(n*pstd/p)^nui where n = number of moles in mixture
        inline scalar Kn
        (
            const scalar p,
            const scalar T,
            const scalar n
        ) const;

// Mole specific derived properties

    //- Heat capacity at constant pressure [J/kmol/K]
    inline scalar cp
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Absolute Enthalpy [J/kmol]
    inline scalar ha
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Sensible enthalpy [J/kmol]
    inline scalar hs
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Chemical enthalpy [J/kmol]
    inline scalar hc() const;

    //- Entropy [J/kmol/K]
    inline scalar s
    (
        const scalar p,
        const scalar T
    ) const;

    //- Enthalpy/Internal energy [J/kmol]
    inline scalar he
    (
        const scalar rho,
        const scalar e,
        const scalar T
    ) const;

    //- Heat capacity at constant volume [J/kmol/K]
    inline scalar cv
    (
        const scalar rho,

            const scalar e,
            const scalar T
        ) const;

        //- Sensible internal energy [J/kmol]
        inline scalar es
        (
            const scalar rho,
            const scalar e,
            const scalar T
        ) const;

        //- Absolute internal energy [J/kmol]
        inline scalar ea
        (
            const scalar rho,
            const scalar e,
            const scalar T
        ) const;

        //- Gibbs free energy [J/kmol]
        inline scalar g
        (
            const scalar p,
            const scalar T
        ) const;

        //- Helmholtz free energy [J/kmol]
        inline scalar a
        (
            const scalar p,
            const scalar T
        ) const;


    // Derivative term used for Jacobian

        //- Derivative of B (acooding to Niemeyer et al.) w.r.t. temperature
        inline scalar dKcdTbyKc(const scalar p, const scalar T) const;

        //- Derivative of cp w.r.t. temperature
        inline scalar dcpdT(const scalar rho, const scalar e, const scalar T) const;


// Energy->temperature  inversion functions

        //- Temperature from enthalpy or internal energy
        //  given an initial temperature T0

        inline scalar TRhoE
        (
            const scalar T,
            const scalar rho,
            const scalar E
        ) const;

        //- Temperature from sensible enthalpy given an initial T0
        inline scalar THs
        (
            const scalar Hs,
            const scalar p,
            const scalar rho,
            const scalar T0
        ) const;

        //- Temperature from absolute enthalpy
        //  given an initial temperature T0
        inline scalar THa
        (
            const scalar Ha,
            const scalar p,
            const scalar rho,
            const scalar T0
        ) const;

        //- Temperature from sensible internal energy
        //  given an initial temperature T0
        inline scalar TEs
        (
            const scalar Es,
            const scalar p,
            const scalar rho,
            const scalar T0
        ) const;

        //- Temperature from absolute internal energy
        //  given an initial temperature T0
        inline scalar TEa
        (
            const scalar Ea,
            const scalar p,
            const scalar rho,
            const scalar T0
        ) const;


// Member Operators

        inline void operator=(const thermoModel&);
        inline void operator+=(const thermoModel&);
        inline void operator*=(const scalar);


    // Friend operators

        friend thermoModel operator+ <ThermoType>
        (
            const thermoModel&,
            const thermoModel&
        );

        friend thermoModel operator* <ThermoType>
        (
            const scalar s,
            const thermoModel&
        );

        friend thermoModel operator== <ThermoType>
        (
            const thermoModel&,
