template<class ThermoType>
inline Foam::scalar
Foam::thermoModel<ThermoType>::K

(
    const scalar p,
    const scalar T
) const
{
    scalar arg = -this->Y()*this->G(Pstd, T)/(RR*T);

    if (arg < 600)
    {
        return exp(arg);
    }
    else
    {
        return rootVGreat;
    }
}


