/*--------------------------------*- C++ -*----------------------------------*\
  | =========                 |                                                 |
  | \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
  |  \\    /   O peration     | Version:  2.3.0                                 |
  |   \\  /    A nd           | Web:      www.OpenFOAM.org                      |
  |    \\/     M anipulation  |                                                 |
  \*---------------------------------------------------------------------------*/
FoamFile
{
  version     2.0;
  format      ascii;
  class       dictionary;
  location    "system";
  object      controlDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

application     blastEulerFoam;

startFrom       startTime;

startTime       0;

stopAt          endTime;

endTime         .0025;

writeControl    adjustableRunTime;

writeInterval   1e-4;

writeFormat     binary;

writePrecision  6;

writeCompression off;

timeFormat      general;

timePrecision   12;

runTimeModifiable true;

adjustTimeStep  yes;

deltaT          1e-7;

maxCo           0.5;

/*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  2.3.0                                 |
|   \\  /    A nd           | Web:      www.OpenFOAM.org                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    location    "system";
    object      decomposeParDict;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

numberOfSubdomains 36; // this is number of proc

// preservePatches (patch0 patch1 patch2);

method         scotch; // automatic

simpleCoeffs // not auto
{
    n               ( 2 2 1 );
    delta           0.001;
}

hierarchicalCoeffs
{
    n               ( 4 3 2 );
    delta           0.001;
    order           xyz;
}

metisCoeffs
{
    // processorWeights ( 1 1 1 1 1 1 );
}

manualCoeffs
{
    dataFile        "";
}

distributed     no;

/*--------------------------------*- C++ -*----------------------------------*\
| =========                 |                                                 |
| \\      /  F ield         | OpenFOAM: The Open Source CFD Toolbox           |
|  \\    /   O peration     | Version:  2.3.0                                 |
|   \\  /    A nd           | Web:      www.OpenFOAM.org                      |
|    \\/     M anipulation  |                                                 |
\*---------------------------------------------------------------------------*/
FoamFile
{
    version     2.0;
    format      ascii;
    class       dictionary;
    location    "system";
    object      fvSchemes;
}
// * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * * //

fluxSchemes
{
    gas
    {
        fluxScheme  HLLC;
    }
    particles
    {
        fluxScheme          AUSM+Up;
        alphaMinFriction    0.5;
        alphaMax            0.63;
    }
}

ddtSchemes
{
    default         Euler;
    timeIntegrator  RK2SSP;
}

gradSchemes
{
    default         cellMDLimited leastSquares 1.0;
}

divSchemes
{
    default         none;
    div(alphaRhoPhi.gas,Yi)         Riemann;
    div(phi.particles,d.particles) Riemann particles;
    div(alphaRhoPhi.particles,d.particles) Riemann particles;

    div((((alpha.gas*rho.gas)*nuEff.gas)*dev2(T(grad(U.gas))))) Gauss linear;
    div(sigma.particles) Gauss linear;
}

laplacianSchemes
{
    default         Gauss linear corrected;
}

interpolationSchemes
{
    default             cubic;
    reconstruct(alpha)  quadraticMUSCL vanAlbada;
    reconstruct(rho)    quadraticMUSCL vanAlbada;
    reconstruct(U)      quadraticMUSCL vanAlbada;
    reconstruct(e)      quadraticMUSCL vanAlbada;
    reconstruct(p)      quadraticMUSCL vanAlbada;
    reconstruct(speedOfSound) quadraticMUSCL vanAlbada;
    "reconstruct\(Y.*\)" quadraticMUSCL vanAlbada;
    reconstruct(Theta)  quadraticMUSCL vanAlbada;
}

snGradSchemes
{
    default         corrected;
}


