cellSize 0.1;

nx  #calc "round($R / $cellSize)";
ny  #calc "round($H / $cellSize)";

A   1.0;

x #calc "$R * cos($A * Foam::constant::mathematical::pi/180)";
z #calc "$R * sin($A  * Foam::constant::mathematical::pi/180)";
