            const scalar MN2 = 14.0067*2.0;
            const scalar MO2 = 15.9988*2.0;

            scalar yRel = y - 0.03;
            scalar _10H2 =
              - 3.50957e+04*pow5(yRel)
              - 3.26065e+04*pow4(yRel)
              - 5.25765e+03*pow3(yRel)
              - 2.62149e+02*sqr(yRel)
              - 3.84660e-01*yRel
              + 1.99094e-01;

            scalar _20H2 =
                1.84717e+05*pow5(yRel)
