        p1       (0.0 0.0 -1); // start point on cylinder axis
        p2       (0.0 0.0  1);  // end point on cylinder axis
        radius   0.02451;
        fieldValues
        (
            volScalarFieldValue ft  0.0217406435288288
            volScalarFieldValue b   0
            volScalarFieldValue T   2448.5
        );
    }
)

